INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`RewardText`)='4c9203d75db2ab1abaaef6126216f246','Молодец, ты отлично справился. Вот твоя доля, $N. Ты можешь заработать еще больше – на этом острове еще полно должников.',''),0 FROM `quest_offer_reward` b WHERE b.`ID`=11464 AND (MD5(b.`RewardText`)='4c9203d75db2ab1abaaef6126216f246') ON DUPLICATE KEY UPDATE `RewardText`=IF(VALUES(`RewardText`)<>'' AND COALESCE(`quest_offer_reward_locale`.`RewardText`,'')='',VALUES(`RewardText`),`quest_offer_reward_locale`.`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`RewardText`)='148aa5569ba24b765eca339e48c08934','Я поражен твоим успехам, $N. А меня, знаешь ли, не так-то легко поразить.',''),0 FROM `quest_offer_reward` b WHERE b.`ID`=11466 AND (MD5(b.`RewardText`)='148aa5569ba24b765eca339e48c08934') ON DUPLICATE KEY UPDATE `RewardText`=IF(VALUES(`RewardText`)<>'' AND COALESCE(`quest_offer_reward_locale`.`RewardText`,'')='',VALUES(`RewardText`),`quest_offer_reward_locale`.`RewardText`);
