INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`RewardText`)='c194f105c0c0274000f1b5cc433b6b51','Орфус – хороший клыкарр, и один из лучших наших воинов. Я знал, что на него можно положиться.$B$BНу-ка, что там он мне передал?',''),0 FROM `quest_offer_reward` b WHERE b.`ID`=11507 AND (MD5(b.`RewardText`)='c194f105c0c0274000f1b5cc433b6b51') ON DUPLICATE KEY UPDATE `RewardText`=IF(VALUES(`RewardText`)<>'' AND COALESCE(`quest_offer_reward_locale`.`RewardText`,'')='',VALUES(`RewardText`),`quest_offer_reward_locale`.`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`RewardText`)='be6a8183faed0f0ee2df6bcdfc6c842e','Мы должны отыскать все четыре артефакта, $N. Когда мы возвратим святыни, ты положишь их на место, в захоронения.',''),0 FROM `quest_offer_reward` b WHERE b.`ID`=11511 AND (MD5(b.`RewardText`)='be6a8183faed0f0ee2df6bcdfc6c842e') ON DUPLICATE KEY UPDATE `RewardText`=IF(VALUES(`RewardText`)<>'' AND COALESCE(`quest_offer_reward_locale`.`RewardText`,'')='',VALUES(`RewardText`),`quest_offer_reward_locale`.`RewardText`);
