INSERT INTO `quest_request_items_locale` (`ID`,`locale`,`CompletionText`,`VerifiedBuild`) SELECT b.`ID`,'ruRU',IF(MD5(b.`CompletionText`)='5a1ae9cc0bcc3eaac0a982e90b25a133','Донесение Ориона? Давай сюда, живо!$B$B<Нахмурившись, генерал Кракорк просматривает изорванные бумаги.>$B$BПроклятье, именно этого мы и боялись! Ориона и его армию могут в любой момент отбросить!',''),0 FROM `quest_request_items` b WHERE b.`ID`=10289 AND (MD5(b.`CompletionText`)='5a1ae9cc0bcc3eaac0a982e90b25a133') ON DUPLICATE KEY UPDATE `CompletionText`=IF(VALUES(`CompletionText`)<>'' AND COALESCE(`quest_request_items_locale`.`CompletionText`,'')='',VALUES(`CompletionText`),`quest_request_items_locale`.`CompletionText`);
